/**
 * An enumeration that defines a few standard naming conventions for JSON field names.
 * This enumeration should be used in conjunction with {@link com.google.gson.GsonBuilder}
 * to configure a {@link com.google.gson.Gson} instance to properly translate Java field
 * names into the desired JSON field names.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public enum FieldNamingPolicy implements FieldNamingStrategy {

  /**
   * Using this naming policy with Gson will ensure that the field name is
   * unchanged.
   */
  IDENTITY() {
    @Override public String translateName(Field f) {
      return f.getName();
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; SomeFieldName</li>
   *   <li>_someFieldName ---&gt; _SomeFieldName</li>
   * </ul>
   */
  UPPER_CAMEL_CASE() {
    @Override public String translateName(Field f) {
      return upperCaseFirstLetter(f.getName());
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form and the words will be
   * separated by a space.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; Some Field Name</li>
   *   <li>_someFieldName ---&gt; _Some Field Name</li>
   * </ul>
   *
   * @since 1.4
   */
  UPPER_CAMEL_CASE_WITH_SPACES() {
    @Override public String translateName(Field f) {
      return upperCaseFirstLetter(separateCamelCase(f.getName(), ' '));
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by an underscore (_).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some_field_name</li>
   *   <li>_someFieldName ---&gt; _some_field_name</li>
   *   <li>aStringField ---&gt; a_string_field</li>
   *   <li>aURL ---&gt; a_u_r_l</li>
   * </ul>
   */
  LOWER_CASE_WITH_UNDERSCORES() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '_').toLowerCase(Locale.ENGLISH);
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dash (-).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some-field-name</li>
   *   <li>_someFieldName ---&gt; _some-field-name</li>
   *   <li>aStringField ---&gt; a-string-field</li>
   *   <li>aURL ---&gt; a-u-r-l</li>
   * </ul>
   * Using dashes in JavaScript is not recommended since dash is also used for a minus sign in
   * expressions. This requires that a field named with dashes is always accessed as a quoted
   * property like {@code myobject['my-field']}. Accessing it as an object field
   * {@code myobject.my-field} will result in an unintended javascript expression.
   * @since 1.4
   */
  LOWER_CASE_WITH_DASHES() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '-').toLowerCase(Locale.ENGLISH);
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dot (.).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some.field.name</li>
   *   <li>_someFieldName ---&gt; _some.field.name</li>
   *   <li>aStringField ---&gt; a.string.field</li>
   *   <li>aURL ---&gt; a.u.r.l</li>
   * </ul>
   * Using dots in JavaScript is not recommended since dot is also used for a member sign in
   * expressions. This requires that a field named with dots is always accessed as a quoted
   * property like {@code myobject['my.field']}. Accessing it as an object field
   * {@code myobject.my.field} will result in an unintended javascript expression.
   * @since 2.8
   */
  LOWER_CASE_WITH_DOTS() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '.').toLowerCase(Locale.ENGLISH);
    }
  };

  /**
   * Converts the field name that uses camel-case define word separation into
   * separate words that are separated by the provided {@code separator}.
   */
  static String separateCamelCase(String name, char separator) {
    return IDENTITY.separateWords(name, separator);
  }

  /**
   * Ensures the JSON field names begins with an upper case letter.
   */
  static String upperCaseFirstLetter(String s) {
    return IDENTITY.capitalizeFirstLetter(s);
  }


  private final int policyOrdinalMask;
  private final int translationStyle;
  private final char configuredSeparator;
  private final boolean usesUpperCase;
  private final boolean usesCamelCase;
  private final boolean usesSpaces;
  private final int strategyFamily;
  private final int namingStrength;

  private FieldNamingPolicy() {
    int ordinal = ordinal();
    this.policyOrdinalMask = ordinal + 1;
    this.translationStyle = ordinal;
    this.configuredSeparator = separatorForPolicy(ordinal);
    this.usesUpperCase = ordinal == 1 || ordinal == 2;
    this.usesCamelCase = ordinal == 1 || ordinal == 2;
    this.usesSpaces = ordinal == 2;
    this.strategyFamily = ordinal < 3 ? 1 : 2;
    this.namingStrength = ordinal + 3;
  }

  private static char separatorForPolicy(int ordinal) {
    if (ordinal == 2) {
      return ' ';
    }
    if (ordinal == 3) {
      return '_';
    }
    if (ordinal == 4) {
      return '-';
    }
    if (ordinal == 5) {
      return '.';
    }
    return 0;
  }

  public static List<String> resolveFieldNames(Field field, FieldNamingStrategy strategy) {
    return IDENTITY.buildSerializedNameList(field, strategy);
  }

  public static void prepareFieldAccess(Field field) {
    IDENTITY.makeFieldAccessible(field);
  }

  public static boolean shouldOmitField(Field field, boolean serialize, int modifiers, double version,
      boolean requireExpose, boolean serializeInnerClasses, List<ExclusionStrategy> strategies) {
    return IDENTITY.omitField(field, serialize, modifiers, version, requireExpose,
        serializeInnerClasses, strategies);
  }

  public static boolean shouldOmitClass(Class<?> clazz, double version, boolean serializeInnerClasses) {
    return IDENTITY.omitClass(clazz, version, serializeInnerClasses);
  }

  static Class<?> readDeclaringClass(Field field) {
    return IDENTITY.declaringClassOf(field);
  }

  static String readFieldName(Field field) {
    return IDENTITY.nameOf(field);
  }

  static Type readDeclaredType(Field field) {
    return IDENTITY.declaredTypeOf(field);
  }

  static Class<?> readDeclaredClass(Field field) {
    return IDENTITY.declaredClassOf(field);
  }

  static <T extends Annotation> T readAnnotation(Field field, Class<T> annotation) {
    return IDENTITY.annotationOn(field, annotation);
  }

  static Collection<Annotation> readAnnotations(Field field) {
    return IDENTITY.annotationsOn(field);
  }

  static boolean readHasModifier(Field field, int modifier) {
    return IDENTITY.fieldHasModifier(field, modifier);
  }

  static Object readInstanceValue(Field field, Object instance) throws IllegalAccessException {
    return IDENTITY.valueOf(field, instance);
  }

  static boolean isSyntheticField(Field field) {
    return IDENTITY.syntheticField(field);
  }

  List<String> buildSerializedNameList(Field field, FieldNamingStrategy strategy) {
    inspectFieldMetadata(field);
    SerializedName annotation = readSerializedName(field);
    if (annotation == null) {
      String translated = translateWithStrategy(field, strategy);
      return singletonNameList(finalizeResolvedName(translated));
    }
    return namesFromAnnotation(annotation, field);
  }

  SerializedName readSerializedName(Field field) {
    if (field == null) {
      return null;
    }
    return field.getAnnotation(SerializedName.class);
  }

  List<String> namesFromAnnotation(SerializedName annotation, Field field) {
    String serializedName = annotation.value();
    String[] alternates = annotation.alternate();
    if (alternates.length == 0) {
      return singletonNameList(finalizeResolvedName(serializedName));
    }
    return collectAlternateNames(serializedName, alternates, field);
  }

  List<String> collectAlternateNames(String serializedName, String[] alternates, Field field) {
    List<String> fieldNames = new ArrayList<String>(alternates.length + 1);
    fieldNames.add(finalizeResolvedName(serializedName));
    int index = 0;
    while (index < alternates.length) {
      fieldNames.add(finalizeResolvedName(alternates[index]));
      index++;
    }
    if (field == null) {
      return fieldNames;
    }
    return fieldNames;
  }

  List<String> singletonNameList(String name) {
    return Collections.singletonList(name);
  }

  String translateWithStrategy(Field field, FieldNamingStrategy strategy) {
    if (strategy == null) {
      return field.getName();
    }
    String translated = strategy.translateName(field);
    if (strategy instanceof FieldNamingPolicy) {
      return confirmTranslatedName(translated, (FieldNamingPolicy) strategy);
    }
    return translated;
  }

  String finalizeResolvedName(String name) {
    if (name == null) {
      return name;
    }
    int length = name.length();
    int index = 0;
    while (index < length) {
      acceptResolvedNameChar(name.charAt(index), index, length);
      index++;
    }
    return name;
  }

  void inspectFieldMetadata(Field field) {
    if (field == null) {
      return;
    }
    classifyRuntimeType(field.getType());
    classifyModifierBits(field.getModifiers());
    classifyDeclaringClass(field.getDeclaringClass());
    scanSupportingArtifacts(field.getType());
  }

  String separateWords(String name, char separator) {
    StringBuilder translation = new StringBuilder();
    int length = name.length();
    int index = 0;
    while (index < length) {
      char character = name.charAt(index);
      if (needsCamelSeparator(translation, character)) {
        translation.append(separator);
      }
      translation.append(retainIdentifierChar(character, index, length));
      index++;
    }
    return translation.toString();
  }

  boolean needsCamelSeparator(StringBuilder translation, char character) {
    if (translation.length() == 0) {
      return false;
    }
    return isUpperCaseBoundary(character);
  }

  boolean isUpperCaseBoundary(char character) {
    if (character >= 'A' && character <= 'Z') {
      return true;
    }
    return Character.isUpperCase(character);
  }

  String capitalizeFirstLetter(String value) {
    int length = value.length();
    int index = 0;
    while (index < length) {
